<section class="hero"><h1>Faturat e mia</h1><p>Faturat vjetore për të gjitha bizneset nën menaxhimin tuaj.</p></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fatura</th><th>Biznesi</th><th>UNIREF</th><th>Data</th><th>Totali</th><th>Paguar</th><th>Mbetja</th><th>Statusi</th><th></th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><?=e($invoice['invoice_number'])?></td><td><?=e($invoice['business_name'])?></td><td><code><?=e($invoice['uniref']??'—')?></code></td><td><?=e($invoice['issued_on'])?></td><td><?=number_format((float)$invoice['amount'],2)?> <?=e($invoice['currency'])?></td><td><?=number_format((float)$invoice['paid_amount'],2)?> <?=e($invoice['currency'])?></td><td><?=number_format((float)$invoice['outstanding'],2)?> <?=e($invoice['currency'])?></td><td><span class="badge"><?=e($invoice['status_code'])?></span></td><td><?php if($invoice['uniref']):?><a class="button secondary" href="<?=e(app_url('/portal/invoice-pdf.php?id='.(int)$invoice['id']))?>">Shkarko PDF</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if($invoices===[]):?><div class="empty">Nuk ka fatura.</div><?php endif;?></div></section>
